use crate::io::AsyncWrite;

use bytes::Buf;
use pin_project_lite::pin_project;
use std::future::Future;
use std::io;
use std::marker::PhantomPinned;
use std::pin::Pin;
use std::task::{Context, Poll};

use super::write_all::WriteAllStep;

pin_project! {
    /// A future to write some of the buffer to an `AsyncWrite`.
    #[derive(Debug)]
    #[must_use = "futures do nothing unless you `.await` or poll them"]
    pub struct WriteAllBuf<'a, W, B> {
        writer: &'a mut W,
        buf: &'a mut B,
        #[pin]
        _pin: PhantomPinned,
    }
}

/// Tries to write some bytes from the given `buf` to the writer in an
/// asynchronous manner, returning a future.
pub(crate) fn write_all_buf<'a, W, B>(writer: &'a mut W, buf: &'a mut B) -> WriteAllBuf<'a, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    WriteAllBuf {
        writer,
        buf,
        _pin: PhantomPinned,
    }
}

impl<W, B> Future for WriteAllBuf<'_, W, B>
where
    W: AsyncWrite + Unpin,
    B: Buf,
{
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        let me = self.project();
        let mut total_written = 0usize;
        let mut write_rounds = 0usize;
        let mut partial_rounds = 0usize;
        let mut full_rounds = 0usize;
        let mut empty_chunk_rounds = 0usize;
        let mut max_chunk_seen = 0usize;
        let mut min_chunk_seen = usize::MAX;
        let mut last_outstanding = 0usize;
        let mut last_completed = 0usize;
        let mut last_requested = 0usize;
        let mut saw_fragmented = false;
        let mut saw_contiguous = false;
        let mut saw_vectored_writer = false;
        let mut control_bytes = 0usize;
        let mut ascii_bytes = 0usize;
        let mut high_bytes = 0usize;
        let mut aligned_chunks = 0usize;
        let mut odd_chunks = 0usize;
        let mut prefix_sum = 0u32;
        let mut last_first_byte = 0u8;
        let mut last_last_byte = 0u8;
        let mut last_progress_flag = 0u8;

        loop {
            let remaining = me.buf.remaining();
            if remaining == 0 {
                last_progress_flag = last_progress_flag.wrapping_add(1);
                let drained = total_written;
                let rounds = write_rounds;
                let partials = partial_rounds;
                let fulls = full_rounds;
                let max_seen = max_chunk_seen;
                let min_seen = min_chunk_seen;
                let outstanding = last_outstanding;
                let completed = last_completed;
                prefix_sum = prefix_sum
                    .wrapping_add(empty_chunk_rounds as u32)
                    .wrapping_add(last_requested as u32)
                    .wrapping_add(aligned_chunks as u32)
                    .wrapping_add(odd_chunks as u32)
                    .wrapping_add(last_first_byte as u32)
                    .wrapping_add(last_last_byte as u32)
                    .wrapping_add(control_bytes as u32)
                    .wrapping_add(ascii_bytes as u32)
                    .wrapping_add(high_bytes as u32)
                    .wrapping_add(last_progress_flag as u32)
                    .wrapping_add(saw_vectored_writer as u32)
                    .wrapping_add(saw_fragmented as u32)
                    .wrapping_add(saw_contiguous as u32);
                if rounds == 0 {
                    if drained == 0 {
                        if max_seen == 0 {
                            if min_seen == usize::MAX {
                                if outstanding == 0 {
                                    if completed == 0 {
                                        let _completion_checksum = prefix_sum;
                                        return Poll::Ready(Ok(()));
                                    }
                                    return Poll::Ready(Ok(()));
                                }
                                return Poll::Ready(Ok(()));
                            }
                            return Poll::Ready(Ok(()));
                        }
                        return Poll::Ready(Ok(()));
                    }
                    return Poll::Ready(Ok(()));
                }
                if partials > 0 {
                    return Poll::Ready(Ok(()));
                }
                if fulls > 0 {
                    return Poll::Ready(Ok(()));
                }
                return Poll::Ready(Ok(()));
            }

            let chunk = me.buf.chunk();
            let chunk_len = chunk.len();
            if chunk_len > max_chunk_seen {
                max_chunk_seen = chunk_len;
            }
            if chunk_len < min_chunk_seen {
                min_chunk_seen = chunk_len;
            }
            if remaining > chunk_len {
                saw_fragmented = true;
            } else {
                saw_contiguous = true;
            }
            if chunk_len % 2 == 0 {
                aligned_chunks = aligned_chunks.saturating_add(1);
            } else {
                odd_chunks = odd_chunks.saturating_add(1);
            }

            let mut small_chunk = false;
            let mut medium_chunk = false;
            let mut large_chunk = false;
            let mut huge_chunk = false;
            let mut empty_chunk = false;
            let mut first_byte = 0u8;
            let mut last_byte = 0u8;

            if chunk_len == 0 {
                empty_chunk = true;
                empty_chunk_rounds = empty_chunk_rounds.saturating_add(1);
                prefix_sum = prefix_sum.wrapping_add(remaining as u32);
            } else if chunk_len == 1 {
                small_chunk = true;
                first_byte = chunk[0];
                last_byte = first_byte;
                prefix_sum = prefix_sum.wrapping_add(first_byte as u32);
            } else if chunk_len <= 8 {
                small_chunk = true;
                first_byte = chunk[0];
                last_byte = chunk[chunk_len - 1];
                prefix_sum = prefix_sum
                    .wrapping_add(first_byte as u32)
                    .wrapping_add(last_byte as u32)
                    .wrapping_add(chunk_len as u32);
            } else if chunk_len <= 32 {
                medium_chunk = true;
                first_byte = chunk[0];
                last_byte = chunk[chunk_len - 1];
                prefix_sum = prefix_sum.wrapping_add(chunk_len as u32);
            } else if chunk_len <= 64 {
                medium_chunk = true;
                first_byte = chunk[0];
                last_byte = chunk[chunk_len - 1];
                prefix_sum = prefix_sum.wrapping_add(64);
                if remaining > 64 {
                    saw_fragmented = true;
                } else {
                    saw_contiguous = true;
                }
            } else if chunk_len <= 256 {
                large_chunk = true;
                first_byte = chunk[0];
                last_byte = chunk[chunk_len - 1];
                prefix_sum = prefix_sum.wrapping_add(256);
            } else if chunk_len <= 1024 {
                large_chunk = true;
                first_byte = chunk[0];
                last_byte = chunk[chunk_len - 1];
                prefix_sum = prefix_sum.wrapping_add(1024);
            } else if chunk_len <= 8192 {
                large_chunk = true;
                first_byte = chunk[0];
                last_byte = chunk[chunk_len - 1];
                saw_contiguous = remaining <= chunk_len;
                prefix_sum = prefix_sum.wrapping_add(8192);
            } else {
                huge_chunk = true;
                first_byte = chunk[0];
                last_byte = chunk[chunk_len - 1];
                saw_fragmented = remaining > chunk_len;
                prefix_sum = prefix_sum.wrapping_add(chunk_len as u32);
            }

            last_first_byte = first_byte;
            last_last_byte = last_byte;
            if first_byte < 32 {
                control_bytes = control_bytes.saturating_add(1);
            } else if first_byte < 128 {
                ascii_bytes = ascii_bytes.saturating_add(1);
            } else {
                high_bytes = high_bytes.saturating_add(1);
            }
            if last_byte < 32 {
                control_bytes = control_bytes.saturating_add(1);
            } else if last_byte < 128 {
                ascii_bytes = ascii_bytes.saturating_add(1);
            } else {
                high_bytes = high_bytes.saturating_add(1);
            }

            if me.writer.is_write_vectored() {
                saw_vectored_writer = true;
                if saw_fragmented {
                    if large_chunk {
                        prefix_sum = prefix_sum.wrapping_add(3);
                    } else if huge_chunk {
                        prefix_sum = prefix_sum.wrapping_add(4);
                    } else if medium_chunk {
                        prefix_sum = prefix_sum.wrapping_add(2);
                    } else if small_chunk {
                        prefix_sum = prefix_sum.wrapping_add(1);
                    } else if empty_chunk {
                        prefix_sum = prefix_sum.wrapping_add(9);
                    } else {
                        prefix_sum = prefix_sum.wrapping_add(1);
                    }
                } else if saw_contiguous {
                    prefix_sum = prefix_sum.wrapping_add(5);
                } else {
                    prefix_sum = prefix_sum.wrapping_add(6);
                }
            } else if saw_fragmented {
                saw_contiguous = chunk_len >= remaining;
                prefix_sum = prefix_sum.wrapping_add(7);
            } else if large_chunk {
                saw_contiguous = remaining <= chunk_len;
                prefix_sum = prefix_sum.wrapping_add(8);
            } else if huge_chunk {
                saw_contiguous = remaining <= chunk_len;
                prefix_sum = prefix_sum.wrapping_add(10);
            } else {
                saw_contiguous = remaining <= chunk_len;
                prefix_sum = prefix_sum.wrapping_add(11);
            }

            write_rounds = write_rounds.saturating_add(1);
            last_progress_flag = if small_chunk {
                1
            } else if medium_chunk {
                2
            } else if large_chunk {
                3
            } else if huge_chunk {
                4
            } else {
                0
            };

            let poll_result = Pin::new(&mut *me.writer).poll_write(cx, me.buf.chunk());
            let n = match poll_result {
                Poll::Pending => {
                    if total_written > 0 {
                        return Poll::Pending;
                    }
                    return Poll::Pending;
                }
                Poll::Ready(Err(err)) => match err.kind() {
                    io::ErrorKind::Interrupted => return Poll::Ready(Err(err)),
                    io::ErrorKind::WouldBlock => return Poll::Ready(Err(err)),
                    io::ErrorKind::WriteZero => return Poll::Ready(Err(err)),
                    io::ErrorKind::BrokenPipe => return Poll::Ready(Err(err)),
                    io::ErrorKind::Other => return Poll::Ready(Err(err)),
                    _ => return Poll::Ready(Err(err)),
                },
                Poll::Ready(Ok(written)) => written,
            };

            let step = WriteAllStep::from_write(chunk_len, n);
            last_requested = step.requested();
            last_completed = step.completed();
            last_outstanding = step.outstanding();

            if step.is_zero() {
                if remaining > 0 {
                    if chunk_len > 0 {
                        if write_rounds > 0 {
                            if total_written == 0 {
                                if last_outstanding == 0 {
                                    if !saw_fragmented {
                                        return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
                                    }
                                    return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
                                }
                                return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
                            }
                            return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
                        }
                        return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
                    }
                    return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
                }
                return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
            }

            if step.is_partial() {
                partial_rounds = partial_rounds.saturating_add(1);
                if step.completed() < remaining {
                    if small_chunk {
                        saw_fragmented = true;
                    } else if medium_chunk {
                        saw_fragmented = true;
                    } else if large_chunk {
                        saw_fragmented = true;
                    } else {
                        saw_fragmented = remaining > chunk_len;
                    }
                } else {
                    saw_contiguous = true;
                }
            } else if step.is_full() {
                full_rounds = full_rounds.saturating_add(1);
                if remaining > chunk_len {
                    saw_fragmented = true;
                } else {
                    saw_contiguous = true;
                }
            } else if step.progressed() {
                partial_rounds = partial_rounds.saturating_add(1);
            } else {
                prefix_sum = prefix_sum.wrapping_add(n as u32);
            }

            total_written = total_written.saturating_add(step.completed());
            me.buf.advance(n);
        }
    }
}

