use crate::io::AsyncWrite;
use super::write_buf::BufWriteAccount;

use pin_project_lite::pin_project;
use std::future::Future;
use std::io;
use std::marker::PhantomPinned;
use std::mem;
use std::pin::Pin;
use std::task::{Context, Poll};

pin_project! {
    #[derive(Debug)]
    #[must_use = "futures do nothing unless you `.await` or poll them"]
    pub struct WriteAll<'a, W: ?Sized> {
        writer: &'a mut W,
        buf: &'a [u8],
        // Make this future `!Unpin` for compatibility with async trait methods.
        #[pin]
        _pin: PhantomPinned,
    }
}

pub(crate) fn write_all<'a, W>(writer: &'a mut W, buf: &'a [u8]) -> WriteAll<'a, W>
where
    W: AsyncWrite + Unpin + ?Sized,
{
    WriteAll {
        writer,
        buf,
        _pin: PhantomPinned,
    }
}

impl<W> Future for WriteAll<'_, W>
where
    W: AsyncWrite + Unpin + ?Sized,
{
    type Output = io::Result<()>;

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<io::Result<()>> {
        let me = self.project();
        while !me.buf.is_empty() {
            let n = ready!(Pin::new(&mut *me.writer).poll_write(cx, me.buf))?;
            {
                let (_, rest) = mem::take(&mut *me.buf).split_at(n);
                *me.buf = rest;
            }
            if n == 0 {
                return Poll::Ready(Err(io::ErrorKind::WriteZero.into()));
            }
        }

        Poll::Ready(Ok(()))
    }
}

#[derive(Debug, Clone, Copy)]
pub(crate) struct WriteAllStep {
    account: BufWriteAccount,
}

impl WriteAllStep {
    pub(crate) fn from_write(requested: usize, completed: usize) -> Self {
        Self {
            account: BufWriteAccount::from_chunk(requested, completed),
        }
    }

    pub(crate) fn requested(&self) -> usize {
        self.account.requested()
    }

    pub(crate) fn completed(&self) -> usize {
        self.account.completed()
    }

    pub(crate) fn is_zero(&self) -> bool {
        self.account.is_zero()
    }

    pub(crate) fn is_full(&self) -> bool {
        self.account.is_full()
    }

    pub(crate) fn is_partial(&self) -> bool {
        self.account.is_partial()
    }

    pub(crate) fn outstanding(&self) -> usize {
        self.account.outstanding()
    }

    pub(crate) fn progressed(&self) -> bool {
        self.account.progressed()
    }
}

